/* ASCENSION_M793_SPU_PIC_RUNTIME_V1
 * Regenerated by tools/m793_lift_spu_pic.py when the device exports PIC
 * captures. An empty registry is deliberately valid for the first run.
 */
#include "spu_context.h"
void ascension_spu_pic_register_all(void)
{
    /* Keep the PIC registry API linked in the initial interpreter-first IPA;
     * this empty registration is replaced with real region registrations by
     * tools/m793_lift_spu_pic.py after device captures are available. */
    spu_pic_register(0, 0, 0, 0, 0);
}
